import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Order Constants","description":"","frontmatter":{},"headers":[],"relativePath":"api-documentation/v1/order-constants.md","filePath":"api-documentation/v1/order-constants.md"}'),o={name:"api-documentation/v1/order-constants.md"};function l(n,e,c,d,s,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="order-constants" tabindex="-1">Order Constants <a class="header-anchor" href="#order-constants" aria-label="Permalink to &quot;Order Constants&quot;">​</a></h1><h4 id="exchange" tabindex="-1">Exchange <a class="header-anchor" href="#exchange" aria-label="Permalink to &quot;Exchange&quot;">​</a></h4><ul><li>NSE: NSE Equity</li><li>NFO: NSE Futures &amp; Options</li><li>CDS: NSE Currency</li><li>BSE: BSE Equity</li><li>BFO: BSE Futures &amp; Options</li><li>BCD: BSE Currency</li><li>MCX: MCX Commodity</li><li>NCDEX: NCDEX Commodity</li><li>NCO: NSE Commodities </li><li>NSE_INDEX: NSE Index </li><li>BSE_INDEX: BSE Index </li><li>MCX_INDEX: MCX Index </li><li>GLOBAL_INDEX: Global indices like US30, JAPAN225, HANGSENG </li><li>CRYPTO: Crypto exchanges (broker-agnostic; the broker name is carried in <code>brexchange</code>)</li></ul><p>These fourteen values are the complete <code>VALID_EXCHANGES</code> list used by the order and market-data request schemas. Sending anything else returns HTTP 400. Broker capability metadata decides which subset is actually usable for the connected broker.</p><h4 id="product-type" tabindex="-1">Product Type <a class="header-anchor" href="#product-type" aria-label="Permalink to &quot;Product Type&quot;">​</a></h4><ul><li>CNC: Cash &amp; Carry for equity</li><li>NRML: Normal for futures and options</li><li>MIS: Intraday Square off</li></ul><h4 id="price-type" tabindex="-1">Price Type <a class="header-anchor" href="#price-type" aria-label="Permalink to &quot;Price Type&quot;">​</a></h4><ul><li>MARKET: Market Order</li><li>LIMIT: Limit Order</li><li>SL: Stop Loss Limit Order</li><li>SL-M: Stop Loss Market Order</li></ul><h4 id="action" tabindex="-1">Action <a class="header-anchor" href="#action" aria-label="Permalink to &quot;Action&quot;">​</a></h4><ul><li>BUY: Buy</li><li>SELL: Sell</li></ul><p>Order schemas accept the lowercase spellings <code>buy</code> and <code>sell</code> as well.</p><h4 id="derivative-exchanges" tabindex="-1">Derivative Exchanges <a class="header-anchor" href="#derivative-exchanges" aria-label="Permalink to &quot;Derivative Exchanges&quot;">​</a></h4><p>Expiry lookup, Option Greeks, and batch Option Greeks validate <code>exchange</code> against a narrower derivatives list rather than the full exchange set:</p><ul><li>NFO, BFO, MCX, CDS, NCO, BCD, NCDEX, CRYPTO</li></ul><p>GTT placement and modification accept only <code>CNC</code> or <code>NRML</code> for <code>product</code>; <code>MIS</code> is rejected because a GTT can rest for days. GTT <code>pricetype</code> is restricted to <code>LIMIT</code> or <code>MARKET</code>.</p>',15)])])}const m=a(o,[["render",l]]);export{p as __pageData,m as default};
